namespace Database\Seeders;use App\Models\AgreementTemplate;use Illuminate\Database\Seeder;
class AgreementTemplateSeeder extends Seeder {public function run():void{AgreementTemplate::updateOrCreate(['slug'=>'helper-home-standard-service-agreement'],['name'=>'Helper Home Standard Service Agreement','title'=>'Service Agreement','intro_text'=>'This agreement records the service arrangement accepted by the customer and Helper Home.','terms_content'=>"IMPORTANT: This template is a neutral operational starting point. Final wording should be reviewed by the business or its legal advisor.\n\n1. Service Scope\nServices will be provided according to the assignment details and mutually agreed responsibilities.\n\n2. Worker Duties\nThe worker will perform the duties recorded in this agreement and reasonable related household duties agreed by the parties.\n\n3. Duty Hours\nDuty hours and rest arrangements are those stated in the service terms. Changes should be mutually agreed.\n\n4. Salary / Payment\nThe customer will pay the agreed worker salary on the mutually agreed schedule.\n\n5. Agency Service Charges\nAgency charges are payable according to the agreed service terms.\n\n6. Leave / Weekly Off\nLeave and weekly-off arrangements are as stated in this agreement or mutually agreed.\n\n7. Accommodation / Food\nWhere applicable, accommodation and food arrangements follow the recorded customer requirement.\n\n8. Replacement Assistance\nReplacement assistance may be provided subject to the applicable service terms, availability of suitable staff, and the conditions agreed between Helper Home and the customer.\n\n9. Conduct & Responsibility\nAll parties are expected to communicate respectfully and promptly report material service concerns.\n\n10. Cancellation / Termination\nCancellation or termination should follow the mutually agreed notice and service conditions.\n\n11. Verification\nAny verification statement must reflect the worker's actual verification record at the time of this agreement.\n\n12. Confidentiality / Privacy\nPersonal and household information should be handled only for legitimate service purposes.\n\n13. Dispute / General Terms\nConcerns should first be addressed through good-faith discussion between the parties and Helper Home.",'is_default'=>true,'is_active'=>true]);}}
